CREATE TABLE IF NOT EXISTS public.vice_estate_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), program text NOT NULL CHECK(program IN ('VICE','V4X')), holder_id uuid NOT NULL REFERENCES public.holders(id) ON DELETE RESTRICT, units numeric(20,0) NOT NULL CHECK(units>0 AND units<=7500000), status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','RESERVED','DISTRIBUTED','REVOKED')), created_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES auth.users(id), approved_at timestamptz, reserved_at timestamptz, distributed_at timestamptz, correlation_id uuid UNIQUE); ALTER TABLE public.vice_estate_allocations ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.vice_estate_allocations FROM PUBLIC, anon, authenticated;
